$ErrorActionPreference='Stop'
$PSNativeCommandUseErrorActionPreference=$false
$controlRoot='C:\Game Dev\Emulators\codex-lanes\world-emit23\ntfs-compression-controls-v1'
if(Test-Path -LiteralPath $controlRoot){throw 'Preserve prior controls; never reuse a destination'}
$parent=Get-Item -LiteralPath (Split-Path -Parent $controlRoot)
if(($parent.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0){throw 'Reparse parent refused'}
New-Item -ItemType Directory -Path $controlRoot|Out-Null
Add-Type -TypeDefinition @"
using System;using System.ComponentModel;using System.Runtime.InteropServices;using Microsoft.Win32.SafeHandles;
public static class OwnedNtfsCompressionControlsV1 {
 [StructLayout(LayoutKind.Sequential)] struct Info {public uint Attr;public System.Runtime.InteropServices.ComTypes.FILETIME Create,Access,Write;public uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
 [StructLayout(LayoutKind.Sequential)] struct Standard {public long Allocation,Length;public uint Links;public byte Deleted,Directory;}
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle CreateFile(string p,uint a,uint s,IntPtr sec,uint c,uint f,IntPtr t);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(SafeFileHandle h,out Info f);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandleEx(SafeFileHandle h,int c,out Standard f,uint n);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern uint GetCompressedFileSize(string p,out uint high);
 public sealed class Result {public string FileId;public uint Links;public long LogicalBytes,StandardAllocationBytes,PhysicalStorageBytes;}
 public static Result Read(string p){using(var h=CreateFile(p,0x80,7,IntPtr.Zero,3,0x80,IntPtr.Zero)){if(h.IsInvalid)throw new Win32Exception(Marshal.GetLastWin32Error());Info f;Standard s;if(!GetFileInformationByHandle(h,out f)||!GetFileInformationByHandleEx(h,1,out s,(uint)Marshal.SizeOf(typeof(Standard))))throw new Win32Exception(Marshal.GetLastWin32Error());uint high;uint low=GetCompressedFileSize(p,out high);if(low==0xffffffff)throw new Win32Exception(Marshal.GetLastWin32Error());return new Result{FileId=f.Volume.ToString("X8")+":"+f.IndexHigh.ToString("X8")+f.IndexLow.ToString("X8"),Links=f.Links,LogicalBytes=s.Length,StandardAllocationBytes=s.Allocation,PhysicalStorageBytes=((long)high<<32)|low};}}
}
"@
$compact=Join-Path $env:windir 'System32\compact.exe'
$script:nativeCalls=[Collections.Generic.List[object]]::new()
$pattern=[Text.Encoding]::ASCII.GetBytes('OWNED SYNTHETIC NTFS LZNT1 COMPRESSION CONTROL; NO GAME OR EXECUTABLE DATA. ')
$payload=[byte[]]::new(262144);for($i=0;$i-lt$payload.Length;$i++){$payload[$i]=$pattern[$i%$pattern.Length]}
function New-Control([string]$name){$p=Join-Path $controlRoot $name;[IO.File]::WriteAllBytes($p,$payload);return $p}
function State([string]$p){$i=[OwnedNtfsCompressionControlsV1]::Read($p);$f=Get-Item -LiteralPath $p;[pscustomobject]@{Path=$p;FileId=$i.FileId;Links=$i.Links;LogicalBytes=$i.LogicalBytes;StandardAllocationBytes=$i.StandardAllocationBytes;PhysicalStorageBytes=$i.PhysicalStorageBytes;Attributes=[string]$f.Attributes;Readonly=$f.IsReadOnly;Compressed=(($f.Attributes-band[IO.FileAttributes]::Compressed)-ne 0);SHA256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function Same-BytesIdentity($baseline,$current){if($baseline.FileId-ne$current.FileId-or$baseline.SHA256-ne$current.SHA256-or$baseline.LogicalBytes-ne$current.LogicalBytes-or$current.Links-ne 1){throw 'Byte/identity/size/link-count mutation'};if(-not [Linq.Enumerable]::SequenceEqual([byte[]][IO.File]::ReadAllBytes($current.Path),[byte[]]$payload)){throw 'Full authored bytes changed'}}
function Native-Compact([string]$verb,[string]$path){$args=@($verb,'/F','/Q',$path);$text=(& $compact @args 2>&1|Out-String);$rc=$LASTEXITCODE;$call=[pscustomobject]@{Arguments=$args;ExitCode=$rc;Output=$text};$script:nativeCalls.Add($call);return $call}
function Closed-Control-Compact([string]$verb,[string]$path){$full=[IO.Path]::GetFullPath($path);if(-not$full.StartsWith($controlRoot+'\',[StringComparison]::OrdinalIgnoreCase)-or [IO.Path]::GetExtension($full)-ne'.dat'){throw 'Out-of-scope control path'};$f=Get-Item -LiteralPath $full;if($f.IsReadOnly-or(($f.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0)){throw 'Readonly/reparse admission refused'};$h=[IO.File]::Open($full,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$h.Dispose();$r=Native-Compact $verb $full;if($r.ExitCode-ne 0){throw 'Native compact nonzero: fail closed'};return $r}
$plain=New-Control 'roundtrip.dat';$before=State $plain;$c=Closed-Control-Compact '/C' $plain;$compressed=State $plain;Same-BytesIdentity $before $compressed;if(-not$compressed.Compressed-or$compressed.PhysicalStorageBytes-ge$before.PhysicalStorageBytes){throw 'No verified ordinary NTFS compression'}
$u=Closed-Control-Compact '/U' $plain;$restored=State $plain;Same-BytesIdentity $before $restored;if($restored.Compressed-or$restored.PhysicalStorageBytes-ne$before.PhysicalStorageBytes){throw 'Compression roundtrip not restored'}
$ro=New-Control 'readonly.dat';$roBefore=State $ro;(Get-Item -LiteralPath $ro).IsReadOnly=$true;$roRejected=$false;$callsBefore=$nativeCalls.Count;try{$null=Closed-Control-Compact '/C' $ro}catch{if($_.Exception.Message-like'Readonly/reparse*'){$roRejected=$true}else{throw}};if(-not$roRejected-or$nativeCalls.Count-ne$callsBefore){throw 'Readonly not rejected before native invocation'};$roAfter=State $ro;Same-BytesIdentity $roBefore $roAfter;if($roAfter.Compressed-or-not$roAfter.Readonly){throw 'Readonly control unexpectedly changed'}
$busy=New-Control 'sharing.dat';$busyBefore=State $busy;$sharingRejected=$false;$handle=[IO.File]::Open($busy,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
try{$callsBefore=$nativeCalls.Count;try{$null=Closed-Control-Compact '/C' $busy}catch{$sharingRejected=$true};if(-not$sharingRejected-or$nativeCalls.Count-ne$callsBefore){throw 'Sharing not rejected before native invocation'};$rawBusy=Native-Compact '/C' $busy;if($rawBusy.ExitCode-eq 0){throw 'Native compact unexpectedly accepted exclusive sharing'}}finally{$handle.Dispose()}
$busyAfter=State $busy;Same-BytesIdentity $busyBefore $busyAfter;if($busyAfter.Compressed){throw 'Busy control unexpectedly compressed'}
$missing=Join-Path $controlRoot 'does-not-exist.dat';$missingResult=Native-Compact '/C' $missing;if($missingResult.ExitCode-eq 0-or(Test-Path -LiteralPath $missing)){throw 'Native missing-path error not fail closed'}
$out=[ordered]@{Schema='OWNED_NTFS_LZNT1_TINY_CONTROLS_V1';SealedUtc=[DateTime]::UtcNow.ToString('o');Status='PASS_TINY_CONTROLS_ONLY';Scope=$controlRoot;Utility=@{Path=$compact;SHA256=(Get-FileHash -LiteralPath $compact -Algorithm SHA256).Hash.ToLowerInvariant();Version=(Get-Item -LiteralPath $compact).VersionInfo.FileVersion};Volume=(Get-Volume -DriveLetter C|Select-Object DriveLetter,FileSystem,SizeRemaining);SyntheticPayloadBytes=$payload.Length;RoundTrip=@{Before=$before;Compressed=$compressed;Restored=$restored;SameFullBytesFileIdLogicalSize=$true};ReadonlyAdmission=@{RejectedBeforeNative=$roRejected;After=$roAfter};SharingAdmission=@{RejectedBeforeNative=$sharingRejected;NativeAlsoRejected=($rawBusy.ExitCode-ne 0);After=$busyAfter};NativeMissingPathErrorRejected=$true;NativeInvocations=@($nativeCalls);CaptureFilesCompressed=0;ExecutableOrGamePayloadUsed=$false;ActualCaptureRatioOrSavingClaimed=$false;Next='Root review and separate ONE existing eligible closed-capture trial admission required.'}
$receipt=Join-Path (Split-Path -Parent $controlRoot) 'NTFS-COMPRESSION-CONTROLS-20261024-v1.json';if(Test-Path -LiteralPath $receipt){throw 'Preserve receipt'};$out|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $receipt -Encoding UTF8
[pscustomobject]@{Status=$out.Status;BeforePhysical=$before.PhysicalStorageBytes;CompressedPhysical=$compressed.PhysicalStorageBytes;RestoredPhysical=$restored.PhysicalStorageBytes;FileIdUnchanged=($before.FileId-eq$restored.FileId);ReadonlyRejected=$roRejected;SharingRejected=$sharingRejected;Receipt=$receipt;ReceiptSHA256=(Get-FileHash -LiteralPath $receipt -Algorithm SHA256).Hash.ToLowerInvariant();CaptureMutation=0}|ConvertTo-Json
